; ============================================== sub stripOpen ====

stripOpen:
; ---- cfgCol()
        call    cfgCol
; ---- cfgGrowW()
        call    cfgGrowW
; ---- boxOpen()
        call    boxOpen
; ---- labelPaint( caption, lightGray, black )
        mov     ax, [stripOpen__caption]
        mov     [labelPaint__at], ax
        mov     byte [labelPaint__fg], 7
        mov     byte [labelPaint__bg], 0
        call    labelPaint
; ---- cfgGrowW()
        call    cfgGrowW
; ---- cfg.gap = u
        mov     byte [cfg__gap], 1
; ---- boxOpen()
        call    boxOpen
        ret

; ============================================== sub stripClose ====

stripClose:
; ---- closeBox()                    // the row of content
        call    closeBox
; ---- closeBox()                    // the captioned column
        call    closeBox
        ret

