        mov     ax, [shell__swatchBody__at]
        mov     [labelPaint__at], ax
        mov     byte [labelPaint__fg], 0
        mov     al, [shell__swatchBody__bg]
        mov     [labelPaint__bg], al        ; u8 -> u8, no widening
        call    labelPaint
; ---- closeBox()
        call    closeBox
        ret

