; ============================================== sub buildShell ====

buildShell:
; ---- cfgCol()
        call    cfgCol
; ---- cfgGrowW()
        call    cfgGrowW
; ---- cfgGrowH()
        call    cfgGrowH
; ---- panelOpen( blue )
        mov     byte [panelOpen__bg], 1
        call    panelOpen
; ---- cfgGrowW()
        call    cfgGrowW
; ---- cfgFixedH( lineHeight )
        mov     word [cfgFixedH__n], 1
        call    cfgFixedH
; ---- cfgInsetX( u )
        mov     byte [cfgInsetX__n], 1
        call    cfgInsetX
; ---- panelOpen( cyan )
        mov     byte [panelOpen__bg], 3
        call    panelOpen
; ---- labelPaint( addr( sMomolo ), black, cyan )
        mov     ax, sMomolo                 ; link-time constant
        mov     [labelPaint__at], ax
        mov     byte [labelPaint__fg], 0
        mov     byte [labelPaint__bg], 3
        call    labelPaint
; ---- cfgGrowW()
        call    cfgGrowW
; ---- cfg.gap = u
        mov     byte [cfg__gap], 1
; ---- boxOpen()
        call    boxOpen
; ---- closeBox()
        call    closeBox
; ---- labelPaint( addr( sGeometry ), black, cyan )
        mov     ax, sGeometry               ; link-time constant
        mov     [labelPaint__at], ax
        mov     byte [labelPaint__fg], 0
        mov     byte [labelPaint__bg], 3
        call    labelPaint
; ---- closeBox()
        call    closeBox
; ---- cfgGrowW()
        call    cfgGrowW
; ---- cfgGrowH()
        call    cfgGrowH
; ---- cfgInset( u )
        mov     byte [cfgInset__n], 1
        call    cfgInset
; ---- cfg.gap = u
        mov     byte [cfg__gap], 1
; ---- boxOpen()
        call    boxOpen
; ---- cfgCol()
        call    cfgCol
; ---- cfgFixedW( 16 * u )
        mov     word [cfgFixedW__n], 16
        call    cfgFixedW
; ---- cfgGrowH()
